code.C:
#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        if (n % 15 == 0) printf("HiHello\n");
        else if (n % 3 == 0) printf("Hi\n");
        else if (n % 5 == 0) printf("Hello\n");
    }
    return 0;
}

