code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n % 15 == 0) System.out.println("HiHello");
            else if (n % 3 == 0) System.out.println("Hi");
            else if (n % 5 == 0) System.out.println("Hello");
        }
    }
}

code.Python3:
import sys

def main():
    s = sys.stdin.read().strip()
    if s:
        n = int(s)
        if n % 15 == 0: print("HiHello")
        elif n % 3 == 0: print("Hi")
        elif n % 5 == 0: print("Hello")

if __name__ == '__main__':
    main()

